function renderObjectList(){const list=state.filtered.slice(0,250);$('#object-list').innerHTML=`<p class="muted" style="grid-column:1/-1">Showing the first ${list.length.toLocaleString()} alphabetically filtered objects. Use search for the complete ${state.filtered.length.toLocaleString()}-object result.</p>${list.sort((a,b)=>a.name.localeCompare(b.name)).map((d)=>`<button type="button" data-object="${escapeHtml(d.objectId)}"><strong>${escapeHtml(d.name)}</strong><br><small>${escapeHtml(labels[d.normalizedStatus]||d.normalizedStatus)} · ${escapeHtml(d.hostName)}</small></button>`).join('')}`;}

function transform(value,log){if(!Number.isFinite(value))return null;if(log){if(value<=0)return null;return Math.log10(value)}return value;}
function drawPlot(){
  if(!state.atlas)return;renderPlotGuide();const canvas=$('#plot'),{width,height}=fitCanvas(canvas),ctx=canvas.getContext('2d'),xKey=$('#plot-x').value||'orbitalPeriodDays',yKey=$('#plot-y').value||'radiusEarth',xLog=$('#plot-x-log').checked,yLog=$('#plot-y-log').checked;const margin={l:70,r:20,t:24,b:55};const points=[];let missingX=0,missingY=0,nonpositive=0;
  for(const d of state.filtered){const xv=d.population[xKey]?.value,yv=d.population[yKey]?.value;if(!Number.isFinite(xv)){missingX++;continue}if(!Number.isFinite(yv)){missingY++;continue}const x=transform(xv,xLog),y=transform(yv,yLog);if(x===null||y===null){nonpositive++;continue}points.push({x,y,d,xv,yv})}
  ctx.clearRect(0,0,width,height);ctx.fillStyle='#07111d';ctx.fillRect(0,0,width,height);if(!points.length){ctx.fillStyle='#9fb1c2';ctx.fillText('No rows have both selected axes under these filters.',30,50);return}const xs=points.map((p)=>p.x),ys=points.map((p)=>p.y),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);const px=(x)=>margin.l+(x-xmin)/(xmax-xmin||1)*(width-margin.l-margin.r),py=(y)=>height-margin.b-(y-ymin)/(ymax-ymin||1)*(height-margin.t-margin.b);
  ctx.strokeStyle='rgba(103,199,236,.15)';ctx.fillStyle='#9fb1c2';ctx.font=`${11*(devicePixelRatio||1)}px sans-serif`;for(let i=0;i<=5;i++){const x=margin.l+i/5*(width-margin.l-margin.r),y=margin.t+i/5*(height-margin.t-margin.b);ctx.beginPath();ctx.moveTo(x,margin.t);ctx.lineTo(x,height-margin.b);ctx.stroke();ctx.beginPath();ctx.moveTo(margin.l,y);ctx.lineTo(width-margin.r,y);ctx.stroke()}ctx.fillText(`${axes[xKey].label} (${axes[xKey].unit})${xLog?' · log10':''}`,width/2-90,height-15);ctx.save();ctx.translate(18,height/2+80);ctx.rotate(-Math.PI/2);ctx.fillText(`${axes[yKey].label} (${axes[yKey].unit})${yLog?' · log10':''}`,0,0);ctx.restore();
  for(const point of points){point.px=px(point.x);point.py=py(point.y);ctx.globalAlpha=.48;ctx.fillStyle=colors[point.d.normalizedStatus]||colors.UNKNOWN;ctx.beginPath();ctx.arc(point.px,point.py,2.3,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;if(state.selected){const point=points.find((p)=>p.d.objectId===state.selected.objectId);if(point){ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(point.px,point.py,7,0,Math.PI*2);ctx.stroke()}}state.plotPoints=points;$('#plot-accounting').textContent=`Plotted ${points.length.toLocaleString()} rows · excluded ${missingX.toLocaleString()} missing X · ${missingY.toLocaleString()} missing Y after X · ${nonpositive.toLocaleString()} nonpositive log values · ${state.atlas.coverage.objects-state.filtered.length} filtered by atlas controls.`;setQuery({plot_x:xKey,plot_y:yKey,plot_x_log:xLog?1:0,plot_y_log:yLog?1:0});
}

function renderPlotGuide(){
  const code=$('#atlas-method').value,node=$('#plot-guide');if(!node)return;if(code==='all'){node.innerHTML='<strong>Why the cloud has this shape</strong><p>Transit surveys preferentially find larger, short-period, edge-on planets. Radial velocity more easily finds massive, short-period companions. Direct imaging favors young, hot planets on wide orbits. Microlensing is sensitive near the lensing star’s Einstein radius. Mixing these methods creates a discovery-shaped catalog—not an unbiased census.</p>';return;}
  const method=state.registry.methods.entries.find((item)=>item.code===code);node.innerHTML=`<strong>${escapeHtml(methodLabel(code))} selection effects</strong><p>${escapeHtml(method?.selectionEffects?.join(' ')||method?.limitations?.join(' ')||'This method does not sample all planet properties equally.')}</p>`;
}

function compareMatches(query){const q=normalize(query);if(!q)return[];const terms=q.split(' '),ranked=[];for(const d of state.atlas.detections){const name=normalize(d.name),host=normalize(d.hostName),ids=normalize(d.sourceObjectIds.join(' '));if(!terms.every((term)=>name.includes(term)||host.includes(term)||ids.includes(term)))continue;ranked.push([name===q?0:name.startsWith(q)?1:host===q?2:3,d])}ranked.sort((a,b)=>a[0]-b[0]||b[1].sourceIds.length-a[1].sourceIds.length||a[1].name.localeCompare(b[1].name));return ranked.slice(0,10).map(([,d])=>d);}
function searchCompare(){const results=compareMatches($('#compare-search').value),box=$('#compare-results');box.innerHTML=results.length?results.map((d)=>`<button type="button" role="option" data-compare-object="${escapeHtml(d.objectId)}"><strong>${escapeHtml(d.name)}</strong><small>${escapeHtml(d.hostName)} · ${escapeHtml(labels[d.normalizedStatus]||d.normalizedStatus)} · ${escapeHtml(sourceLabel(d.primarySourceId))}</small></button>`).join(''):'<p class="muted">No retained object matches.</p>';box.hidden=!$('#compare-search').value;}
function addComparison(id){if(state.compareIds.includes(id)){toast('That object is already in the comparison.');return}if(state.compareIds.length>=4){toast('Remove an object before adding another.');return}state.compareIds.push(id);$('#compare-search').value='';$('#compare-results').hidden=true;renderComparison();setQuery({compare:state.compareIds.join(',')});}
