function bindLab(){const output=$('#lab-output');if(!output)return;const update=()=>{if($('#lab-rp')){const ratio=(Number($('#lab-rp').value)*.0091577)/Number($('#lab-rs').value);output.value=`${(ratio*ratio*1e6).toFixed(0)} ppm`;}else{const mp=Number($('#lab-mp').value),period=Number($('#lab-period').value);output.value=`${(28.4329*(mp/317.83)*Math.pow(period/365.25,-1/3)).toFixed(2)} m/s`;}};$('#method-detail').querySelectorAll('input').forEach((input)=>input.addEventListener('input',update));update();}

function sourceObservationMap(){return new Map((state.sourceMonitor?.observations||[]).map((item)=>[item.sourceId,item]));}
function effectiveSourceState(entry,observations=sourceObservationMap()){if(entry.state==='INGESTED')return'INGESTED';const observed=observations.get(entry.id);if(observed?.state==='AVAILABLE')return'MONITORED_AVAILABLE';if(observed)return observed.state;return entry.state;}
function renderSourcesList(){const entries=state.registry.sources.entries,observations=sourceObservationMap(),monitored=state.sourceMonitor?.observations?.length||0,inactive=entries.filter((entry)=>['NOT_CONFIGURED','BLOCKED_AUTH'].includes(effectiveSourceState(entry,observations))).length,ingested=entries.filter((entry)=>entry.state==='INGESTED').length;$('#source-summary').innerHTML=`<div><span>Active source contracts</span><strong>${entries.length-inactive}</strong></div><div><span>Contributing atlas rows</span><strong>${ingested}</strong></div><div><span>Checked this attempt</span><strong>${monitored}</strong></div><div><span>Inactive, kept for audit</span><strong>${inactive}</strong></div>`;filterSources();}
function filterSources(){const stateFilter=$('#source-state-filter').value,observations=sourceObservationMap(),isInactive=(entry)=>['NOT_CONFIGURED','BLOCKED_AUTH'].includes(effectiveSourceState(entry,observations)),entries=state.registry.sources.entries.filter((entry)=>stateFilter==='all'||(stateFilter==='active'&&!isInactive(entry))||(stateFilter==='inactive'&&isInactive(entry)));$('#source-list').innerHTML=entries.map((entry)=>{const observation=observations.get(entry.id),effective=effectiveSourceState(entry,observations),latest=observation?`${observation.state}${Number.isFinite(observation.recordCount)?` · ${observation.recordCount.toLocaleString()} records`:''}`:'Not checked by current monitor';return`<article class="source-card"><div><h3>${escapeHtml(entry.name)}</h3><p>${escapeHtml(entry.authority)} · ${escapeHtml(entry.role)}</p></div><div><span class="source-state">${escapeHtml(effective)}</span><p class="monitor-line"><strong>Latest check:</strong> ${escapeHtml(latest)}</p></div><div><p><strong>What it contributes:</strong> ${escapeHtml(entry.state==='INGESTED'?'Rows are included in the current atlas.':entry.state==='LIVE_QUERY'||observation?.state==='AVAILABLE'?'The service is queried or monitored; this does not necessarily add planet rows.':'Declared for future coverage, but no ingestion adapter has passed yet.')}</p><p><strong>Scope:</strong> ${escapeHtml(entry.scope)}</p><p><strong>Remaining limitation:</strong> ${escapeHtml(entry.limitation)}</p></div><a href="${escapeHtml(entry.documentationUrl)}" target="_blank" rel="noopener">Official documentation ↗</a></article>`}).join('');}

function csvEscape(value){const text=String(value??'');return/[",\n]/.test(text)?`"${text.replaceAll('"','""')}"`:text;}
