function bindEvents(){
  $('#search-button').addEventListener('click',search);$('#object-search').addEventListener('input',search);$('#object-search').addEventListener('keydown',(event)=>{if(event.key==='Enter'){const first=$('#search-results button');if(first)selectObject(first.dataset.object,{scroll:true});else search()}if(event.key==='Escape')$('#search-results').hidden=true;});
  document.addEventListener('click',(event)=>{const compareButton=event.target.closest('[data-compare-object]'),removeButton=event.target.closest('[data-remove-compare]');if(compareButton){addComparison(compareButton.dataset.compareObject);return}if(removeButton){removeComparison(removeButton.dataset.removeCompare);return}const objectButton=event.target.closest('[data-object]');if(objectButton)selectObject(objectButton.dataset.object,{scroll:objectButton.closest('#search-results')!==null});if(event.target.matches('[data-open-dossier]'))$('#object-evidence').scrollIntoView({behavior:'smooth'});const tab=event.target.closest('.tabs button');if(tab){$$('.tabs button').forEach((b)=>b.classList.toggle('active',b===tab));$$('.tab-panel').forEach((panel)=>panel.hidden=panel.id!==`tab-${tab.dataset.tab}`)}const method=event.target.closest('[data-method]');if(method){state.method=method.dataset.method;renderMethodDetail()}});
  ['#atlas-status','#atlas-method','#atlas-source','#atlas-year-start','#atlas-year-end'].forEach((id)=>$(id).addEventListener('change',applyFilters));$('#atlas-reset').addEventListener('click',()=>{$('#atlas-status').value='all';$('#atlas-method').value='all';$('#atlas-source').value='all';$('#atlas-year-start').value='1780';$('#atlas-year-end').value='2100';applyFilters()});
  $('#sky').addEventListener('click',(event)=>{const point=pickCanvas(event,state.skyPoints,$('#sky'));if(point)selectObject(point.d.objectId)});$('#plot').addEventListener('click',(event)=>{const point=pickCanvas(event,state.plotPoints.map((p)=>({x:p.px,y:p.py,d:p.d})),$('#plot'));if(point)selectObject(point.d.objectId,{scroll:true})});
  ['#plot-x','#plot-y','#plot-x-log','#plot-y-log'].forEach((id)=>$(id).addEventListener('change',drawPlot));$('#source-state-filter').addEventListener('change',filterSources);$('#compare-search').addEventListener('input',searchCompare);$('#compare-search').addEventListener('keydown',(event)=>{if(event.key==='Enter'){const first=$('#compare-results [data-compare-object]');if(first)addComparison(first.dataset.compareObject)}if(event.key==='Escape')$('#compare-results').hidden=true;});
  $('#copy-link').addEventListener('click',async()=>{await navigator.clipboard.writeText(location.href);toast('Object link copied.');});$('#download-object').addEventListener('click',()=>{if(!state.selected)return;download(`${state.selected.objectId}.json`,JSON.stringify({release:state.manifest,atlasRecord:state.selected,nativeRecords:state.selectedDetail?.records||[]},null,2),'application/json')});
  $('#download-all-csv').addEventListener('click',()=>downloadCsv(atlasRows(state.atlas.detections),'worldsindex-atlas.csv'));$('#download-plot').addEventListener('click',()=>downloadCsv(atlasRows(state.plotPoints.map((p)=>p.d)),'worldsindex-filtered-plot.csv'));
  addEventListener('resize',()=>{clearTimeout(bindEvents.resize);bindEvents.resize=setTimeout(()=>{drawSky();drawPlot()},100)});
}

async function init(){
  try{
    const [atlas,registry,manifest,sourceMonitor]=await Promise.all([fetchGzip(new URL('data/sky-detections.json.gz',base)),fetchGzip(new URL('data/registry.json.gz',base)),fetch(new URL('data/manifest.json',base)).then((response)=>response.json()),fetch(new URL('data/source-monitor.json',base)).then((response)=>response.ok?response.json():null).catch(()=>null)]);state.atlas=atlas;state.registry=registry;state.manifest=manifest;state.sourceMonitor=sourceMonitor;
    $('#metric-objects').textContent=atlas.coverage.objects.toLocaleString();$('#metric-records').textContent=atlas.coverage.sourceRecordOccurrences.toLocaleString();$('#metric-sources').textContent=registry.sources.entries.length.toLocaleString();$('#release-time').textContent=`Atlas generated ${new Date(atlas.generatedAt).toLocaleString()} · artifact ${manifest.atlasSha256.slice(0,12)}…`;
    fillSelect($('#atlas-status'),Object.keys(atlas.coverage.statusCounts).sort(),(value)=>`${labels[value]||value} (${atlas.coverage.statusCounts[value].toLocaleString()})`);fillSelect($('#atlas-method'),Object.keys(atlas.coverage.methodCounts).sort(),(value)=>`${methodLabel(value)} (${atlas.coverage.methodCounts[value].toLocaleString()})`);fillSelect($('#atlas-source'),Object.keys(atlas.coverage.sourceCounts).sort(),(value)=>`${sourceLabel(value)} (${atlas.coverage.sourceCounts[value].toLocaleString()})`);for(const [key,axis]of Object.entries(axes)){fillSelect($('#plot-x'),[key],()=>`${axis.label} (${axis.unit})`);fillSelect($('#plot-y'),[key],()=>`${axis.label} (${axis.unit})`)}
    const query=new URLSearchParams(location.search);$('#plot-x').value=query.get('plot_x')||'orbitalPeriodDays';$('#plot-y').value=query.get('plot_y')||'radiusEarth';$('#plot-x-log').checked=query.get('plot_x_log')!=='0';$('#plot-y-log').checked=query.get('plot_y_log')!=='0';$('#atlas-status').value=query.get('status')||'all';$('#atlas-method').value=query.get('method')||'all';$('#atlas-source').value=query.get('source')||'all';$('#atlas-year-start').value=query.get('year_start')||query.get('plot_year_start')||'1780';$('#atlas-year-end').value=query.get('year_end')||query.get('plot_year_end')||'2100';
    bindEvents();renderProviderHealth();renderMethods();renderSourcesList();applyFilters();const requested=query.get('object');if(requested)await selectObject(requested);else await selectObject(atlas.detections.find((d)=>d.objectId==='object-hd-209458-b')?.objectId||atlas.detections[0].objectId);const compareRequested=(query.get('compare')||'object-hd-209458-b,object-trappist-1-e').split(',').filter((id)=>atlas.detections.some((d)=>d.objectId===id));state.compareIds=[...new Set(compareRequested)].slice(0,4);renderComparison();renderDossier();
  }catch(error){console.error(error);document.body.innerHTML=`<main class="workspace"><h1>WorldsIndex could not open this release</h1><p>${escapeHtml(error.message)}</p><p><a href="data/sky-detections.json.gz">Download the catalog artifact directly</a>.</p></main>`;}
}
init();
